  assert.deepEqual(mutes(rs, '2026-07-06', {}), []);
});

// ---------- M4 ----------
const many = (reporter, targets, date = '2026-07-06') => targets.map((h) => R(date, reporter, h));
t('M4 simple pair, defaults', () => {
  const rs = [...many('q', ['a', 'b', 'c', 'd', 'e', 'f']), ...many('l', ['a', 'b', 'c', 'd', 'e', 'f'])];
