  const rs = [...many('q', ['a', 'b', 'c', 'd', 'e', 'f']), ...many('l', ['a', 'b', 'c', 'd', 'e', 'f'])];
  assert.deepEqual(rings(rs, [P('q', '2026-07-22'), P('l', '2026-07-23')]), [['l', 'q']]);
