    now = tmin;
    for (let i = running.length - 1; i >= 0; i--) if (fin[running[i].id] === tmin) { const t = running[i]; running.splice(i, 1); done.add(t.id); for (const [k, u] of Object.entries(t.uses || {})) free[k] += u; }
    scan();
