  const byId = Object.fromEntries(tasks.map((t) => [t.id, t]));
  const crit = new Set(tasks.filter((t) => fin[t.id] === T).map((t) => t.id));
  const shares = (a, b) => Object.keys(a.uses || {}).some((k) => (a.uses[k] > 0) && (b.uses || {})[k] > 0);
