  let C = 0; for (let n = 1; n <= N; n++) if (PVd(n).cmp(EV) <= 0) C = n;
  let ES = Q.of(C);
  if (C + 1 <= N) { const lo = C === 0 ? Z : PVd(C), hi = PVd(C + 1); if (hi.cmp(lo) !== 0) ES = Q.of(C).add(EV.sub(lo).div(hi.sub(lo))); }
